function solve(tree) {
    const build = (arr) => {
        if (arr.length === 0 || arr[0] === null) return null;
        const root = { v: arr[0], l: null, r: null };
        const queue = [root];
        let i = 1;
        while (i < arr.length && queue.length > 0) {
            const node = queue.shift();
            if (i < arr.length) {
                if (arr[i] !== null) {
                    node.l = { v: arr[i], l: null, r: null };
                    queue.push(node.l);
                }
                i += 1;
            }
            if (i < arr.length) {
                if (arr[i] !== null) {
                    node.r = { v: arr[i], l: null, r: null };
                    queue.push(node.r);
                }
                i += 1;
            }
        }
        return root;
    };
    const root = build(tree);
    if (root === null) return [];
    const out = [];
    let level = [root];
    while (level.length > 0) {
        out.push(level[level.length - 1].v);
        const next = [];
        for (const node of level) {
            if (node.l) next.push(node.l);
            if (node.r) next.push(node.r);
        }
        level = next;
    }
    return out;
}

