function solve(tree, p, q) {
    const build = (arr) => {
        if (arr.length === 0 || arr[0] === null) return null;
        const root = { v: arr[0], l: null, r: null };
        const queue = [root];
        let i = 1;
        while (i < arr.length && queue.length > 0) {
            const node = queue.shift();
            if (i < arr.length) {
                if (arr[i] !== null) {
                    node.l = { v: arr[i], l: null, r: null };
                    queue.push(node.l);
                }
                i += 1;
            }
            if (i < arr.length) {
                if (arr[i] !== null) {
                    node.r = { v: arr[i], l: null, r: null };
                    queue.push(node.r);
                }
                i += 1;
            }
        }
        return root;
    };
    const find = (node) => {
        if (node === null || node.v === p || node.v === q) return node;
        const left = find(node.l);
        const right = find(node.r);
        if (left && right) return node;
        return left || right;
    };
    const result = find(build(tree));
    return result === null ? null : result.v;
}

