function solve(roots, sentence) {
    const set = new Set(roots);
    return sentence
        .split(' ')
        .map((word) => {
            for (let len = 1; len <= word.length; len++) {
                const prefix = word.slice(0, len);
                if (set.has(prefix)) return prefix;
            }
            return word;
        })
        .join(' ');
}

