function solve(operations) {
    const root = { count: 0, children: new Map() };
    const copies = new Map();
    const update = (word, delta) => {
        let node = root;
        for (const ch of word) {
            if (!node.children.has(ch)) node.children.set(ch, { count: 0, children: new Map() });
            node = node.children.get(ch);
            node.count += delta;
        }
    };
    const find = (prefix) => {
        let node = root;
        for (const ch of prefix) {
            node = node.children.get(ch);
            if (node === undefined) return null;
        }
        return node;
    };
    const out = [];
    for (const [type, text] of operations) {
        if (type === 'insert') {
            copies.set(text, (copies.get(text) || 0) + 1);
            update(text, 1);
        } else if (type === 'erase') {
            if ((copies.get(text) || 0) > 0) {
                copies.set(text, copies.get(text) - 1);
                update(text, -1);
            }
        } else {
            const node = find(text);
            out.push(node === null ? 0 : node.count);
        }
    }
    return out;
}
